insert into public.lesson_items (lesson_id, idx, kind, en, ar_meaning, translit, example_en, example_ar) values ('step-grammar-conditionals',0,'pattern','If + present, will + verb','شرط ممكن يصير','','If it rains, we will stay home.','لو تمطر، بنقعد بالبيت.');
